    .reg .pred %p<20>;
    .reg .b32 %r<220>;
    .reg .b64 %rd<70>;
    .reg .f32 %f<35>;
    .shared .align 4 .f32 smem_input[1728];
    .shared .align 4 .f32 smem_weight[5184];
    ld.param.u64 %rd1, [input_ptr];
    ld.param.u64 %rd2, [weight_ptr];
    ld.param.u64 %rd3, [bias_ptr];
    ld.param.u64 %rd4, [output_ptr];
    ld.param.u32 %r1, [n_elements];
    ld.param.u32 %r2, [has_bias];
    cvta.to.global.u64 %rd1, %rd1;
    cvta.to.global.u64 %rd2, %rd2;
    cvta.to.global.u64 %rd3, %rd3;
    cvta.to.global.u64 %rd4, %rd4;
    // block/grid indices: gridDim = (OH, OD, B), blockDim = (64,1,1)
    mov.u32 %r10, %ctaid.x;   // oh
    mov.u32 %r11, %ctaid.y;   // od
    mov.u32 %r15, %ctaid.z;   // b
    mov.u32 %r13, %tid.x;     // tid (0..63), tid==ow for ow<62
    // ---- Load input rows (ic,kd,kh) x full width(64) into shared memory once ----
    mov.u32 %r30, 0;    // ic
IC_L_LOOP:
    setp.ge.u32 %p2, %r30, 3;
    @%p2 bra IC_L_DONE;
    mov.u32 %r31, 0;    // kd
KD_L_LOOP:
    setp.ge.u32 %p3, %r31, 3;
    @%p3 bra KD_L_DONE;
    mov.u32 %r32, 0;    // kh
KH_L_LOOP:
    setp.ge.u32 %p4, %r32, 3;
    @%p4 bra KH_L_DONE;
    add.u32 %r33, %r11, %r31;   // id_ = od + kd
    add.u32 %r34, %r10, %r32;   // ih_ = oh + kh
    mul.lo.u32 %r40, %r15, 786432;
    mad.lo.u32 %r40, %r30, 262144, %r40;
    mad.lo.u32 %r40, %r33, 4096, %r40;
    mad.lo.u32 %r40, %r34, 64, %r40;
    add.u32 %r40, %r40, %r13;
    mul.wide.u32 %rd20, %r40, 4;
    add.s64 %rd21, %rd1, %rd20;
    ld.global.f32 %f2, [%rd21];
    mul.lo.u32 %r41, %r30, 9;
    mad.lo.u32 %r41, %r31, 3, %r41;
    add.u32 %r41, %r41, %r32;
    mul.lo.u32 %r42, %r41, 64;
    add.u32 %r42, %r42, %r13;
    mov.u32 %r43, smem_input;
    mad.lo.u32 %r44, %r42, 4, %r43;
    st.shared.f32 [%r44], %f2;
    add.u32 %r32, %r32, 1;
    bra KH_L_LOOP;
KH_L_DONE:
    add.u32 %r31, %r31, 1;
    bra KD_L_LOOP;
KD_L_DONE:
    add.u32 %r30, %r30, 1;
    bra IC_L_LOOP;
IC_L_DONE:
    // ---- Load ALL output-channel weights (64 x 81 = 5184 floats) into
    // shared memory once for the whole CTA lifetime. ----
    mov.u32 %r20, %r13;         // k = tid
LOAD_W_LOOP:
    setp.ge.u32 %p1, %r20, 5184;
    @%p1 bra LOAD_W_DONE;
    mul.wide.u32 %rd10, %r20, 4;
    add.s64 %rd11, %rd2, %rd10;
    ld.global.f32 %f1, [%rd11];
    mov.u32 %r22, smem_weight;
    mad.lo.u32 %r23, %r20, 4, %r22;
    st.shared.f32 [%r23], %f1;
    add.u32 %r20, %r20, 64;
    bra LOAD_W_LOOP;
LOAD_W_DONE:
