    @%p11 bra OC_DONE;
    setp.ge.u32 %p5, %r13, 62;
    @%p5 bra SKIP_COMPUTE;
    mov.u32 %r90, smem_weight;
    mul.lo.u32 %r91, %r16, 324;   // oc_base * 81 * 4 bytes
