    @%p6 bra CIC_DONE;
    mov.u32 %r51, 0;   // kd
CKD_LOOP:
    setp.ge.u32 %p7, %r51, 3;
    @%p7 bra CKD_DONE;
    mov.u32 %r52, 0;   // kh
CKH_LOOP:
    setp.ge.u32 %p8, %r52, 3;
    @%p8 bra CKH_DONE;
    mul.lo.u32 %r55, %r50, 9;
    mad.lo.u32 %r55, %r51, 3, %r55;
    add.u32 %r55, %r55, %r52;
    mul.lo.u32 %r155, %r55, 64;
    mul.lo.u32 %r160, %r50, 27;
    mad.lo.u32 %r160, %r51, 9, %r160;
    mad.lo.u32 %r160, %r52, 3, %r160;
    mul.lo.u32 %r161, %r160, 4;
