    @%p9 bra CKW_DONE;
    add.u32 %r54, %r13, %r53;   // iw = ow + kw
    add.u32 %r56, %r155, %r54;
    mov.u32 %r57, smem_input;
    mad.lo.u32 %r58, %r56, 4, %r57;
    ld.shared.f32 %f6, [%r58];
    mul.lo.u32 %r162, %r53, 4;
    add.u32 %r61, %r161, %r162;
    add.u32 %r62, %r90, %r61;
    ld.shared.f32 %f7, [%r62];
    fma.rn.f32 %f5, %f6, %f7, %f5;
    add.u32 %r63, %r92, %r61;
    ld.shared.f32 %f12, [%r63];
    fma.rn.f32 %f9, %f6, %f12, %f9;
    add.u32 %r64, %r93, %r61;
    ld.shared.f32 %f13, [%r64];
    fma.rn.f32 %f10, %f6, %f13, %f10;
    add.u32 %r65, %r94, %r61;
    ld.shared.f32 %f14, [%r65];
    fma.rn.f32 %f11, %f6, %f14, %f11;
    add.u32 %r66, %r95, %r61;
    ld.shared.f32 %f22, [%r66];
    fma.rn.f32 %f18, %f6, %f22, %f18;
    add.u32 %r67, %r96, %r61;
    ld.shared.f32 %f23, [%r67];
    fma.rn.f32 %f19, %f6, %f23, %f19;
    add.u32 %r68, %r97, %r61;
    ld.shared.f32 %f24, [%r68];
    fma.rn.f32 %f20, %f6, %f24, %f20;
    add.u32 %r69, %r98, %r61;
    ld.shared.f32 %f25, [%r69];
    fma.rn.f32 %f21, %f6, %f25, %f21;
    add.u32 %r53, %r53, 1;
    bra CKW_LOOP;
CKW_DONE:
    add.u32 %r52, %r52, 1;
    bra CKH_LOOP;
CKH_DONE:
    add.u32 %r51, %r51, 1;
    bra CKD_LOOP;
CKD_DONE:
